prices_in_last_7_days = DailyPrices.WHERE(DATEDIFF("days", date, DATETIME('now')) <= 6)

acp_by_ticker_type = prices_in_last_7_days.CALCULATE(
    type=ticker.ticker_type
).PARTITION(
    name="type_groups", by=type
).CALCULATE(
    ticker_type=type,
    average_closing_price=AVG(prices_in_last_7_days.close)
)

prices_in_last_7_days = DailyPrices.WHERE(DATEDIFF("days", date, DATETIME('now')) <= 6)

acp_by_ticker_type = prices_in_last_7_days.CALCULATE(
    type=ticker.ticker_type
).PARTITION(
    name="type_groups", by=type
).CALCULATE(
    ticker_type=type,
    average_closing_price=AVG(prices_in_last_7_days.close)
)

spm_by_ticker = Transactions.WHERE(
    (LOWER(transaction_type) == 'sell') &
    (date_time >= DATETIME('now', '-1 month'))
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    total_sell_amount=SUM(Transactions.amount),
    total_costs=SUM(Transactions.tax + Transactions.commission)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    spm=IFF(
        total_sell_amount > 0,
        (total_sell_amount - total_costs) * 100.0 / total_sell_amount,
        0.0
    )
)

